import { HUMAN_READABLE_FACTOR, ONE_DOLLAR_IN_CREDITS } from '../../../constants';
import { CreditTransactionSubType, CreditTransactionType, Integration } from '../../../generated/graphql';
import { kebabCase, startCase } from 'lodash';
// custom formatter since Intl.NumberFormat has issues in react native
const formatCompact = (num) => {
    if (num >= 1e9) {
        return (num / 1e9).toFixed(1).replace(/\.0$/, '') + 'B';
    }
    if (num >= 1e6) {
        return (num / 1e6).toFixed(1).replace(/\.0$/, '') + 'M';
    }
    if (num >= 1e3) {
        return (num / 1e3).toFixed(1).replace(/\.0$/, '') + 'K';
    }
    return num.toString();
};
export const humanizeCredits = (credits) => {
    const normalized = (BigInt(credits) * 100n) / HUMAN_READABLE_FACTOR;
    const value = Math.ceil(Number(normalized) / 100);
    return formatCompact(value);
};
export const convertCreditsToDollars = (credits, decimals = 2) => {
    const blowUpFactor = 10 ** decimals;
    return (Number((credits * BigInt(blowUpFactor)) / ONE_DOLLAR_IN_CREDITS) /
        blowUpFactor);
};
