export const getCreditUsageImageURL = ({ type, subType }) => {
    switch (type) {
        case CreditTransactionType.INTEGRATION_USAGE:
        case CreditTransactionType.GENERATION_USAGE:
            const imageKey = kebabCase(subType);
            return (integrationImageMap[imageKey] ||
                require('../assets/integrations/custom-integration.png'));
        default: {
            const exhaustiveCheck = type;
            return exhaustiveCheck;
        }
    }
};
function getCreditUsageIntegrationDisplayData({ integration, subType }) {
    return {
        name: integration
            ? getIntegrationDisplayData(integration).name
            : startCase(subType.replace('_', ' ').toLowerCase()),
        thumbnail: getCreditUsageImageURL({
            type: CreditTransactionType.INTEGRATION_USAGE,
            subType
        }),
        description: integration
            ? getIntegrationDisplayData(integration).description
            : ''
    };
}
